def solve():
    """
    Calculates the maximum distance between consecutive gas stations 
    or from the starting point to the first gas station and the last gas station to the end.

    Returns:
        The maximum distance as an integer.
    """

    # Validate input values for 'n' and 'x'
    while True:
        try:
            n = int(input("Enter the number of gas stations: "))
            if n < 0:
                raise ValueError
            break
        except ValueError:
            print("Please enter a non-negative integer.")

    while True:
        try:
            x = int(input("Enter the total distance to end point: "))
            if x <= 0:
                raise ValueError
            break
        except ValueError:
            print("Please enter a positive integer.")

    # Handle special case when 'n' is 0 (no gas stations)
    if n == 0:
        return x

    # Validate input values for 'a'
    while True:
        try:
            a = list(map(int, input(f"Enter {n} space-separated integers representing gas station locations: ").split()))
            if len(a) != n:
                raise ValueError
            break
        except ValueError:
            print("Please enter the correct number of valid integer values.")

    # Ensure all values in 'a' are non-negative and distinct
    a = sorted(list(set([val for val in a if val >= 0])))
    n = len(a)
    if n < 2:
        return max(2 * a[0], 2 * (x - a[-1]))

    # Calculate the maximum distance using the same logic as before, 
    # ensuring we handle edge cases where 'n' is small or gas stations are close to start/end points
    min_distance = float('inf')
    for i in range(len(a) - 1):
        min_distance = min(min_distance, a[i+1] - a[i])

    return max(2 * (a[0]), 2 * ((x-a[-1])), min_distance)

