def solve():
    s = input()
    k = int(input())

    b_count = 0
    A_count_from_end = []

    # Counting 'B's and building A counts in reverse order 
    for i in range(len(s)):
        if s[i] == 'B':
            b_count += 1

        char_from_end_index = len(s) - 1 - i
        if not A_count_from_end or (i % 2) != ((len(A_count_from_end)-1) % 2):
            A_count_from_end.append(0)

        A_count = 0
        for j in range(char_from_end_index, len(s), 2):
            A_count += 1 if s[j] == 'A' else 0

        last_A_counted_index_from_front_idx = (len(A_count_from_end)-1) * 2
        current_A_counted_from_start_plus_A_counted_from_char_index = (
                i + A_count +
                sum([count for j, count in enumerate(A_count_from_end)
                     if ((j+1) % 2 != 0)]))


        # Handling possible index out of boundary
        if last_A_counted_index_from_front_idx < len(s):

            # Compare both from front and back index A counts
            if s[last_A_counted_index_from_front_idx] == 'A':
                current_A_counted_from_start_plus_A_counted_from_char_index += 1


        # Append total count of A's on current step to the corresponding value at list with counting in reverse order from string end
        A_count_from_end.append(current_A_counted_from_start_plus_A_counted_from_char_index)


    min_operations_to_get_k_Bs = float('inf')

    for i, b_in_str_at_i_idx_and_a_in_str_counts \
            in enumerate(b_count + A_count_from_end[1:]):

        if b_in_str_at_i_idx_and_a_in_str_counts >= k:
            min_operations = (k) - b_count 
            if(min_operations_to_get_k_Bs > min_operations):
                min_operations_to_get_k_Bs = min_operations


    if (min_operations_to_get_k_Bs == float('inf')):
        print(-1)

    else:
        print(min_operations_to_get_k_Bs)

import sys

def solve():
    n, k = map(int, input().split())
    s = input()

    b_count = s.count('B')

    if k == b_count:
        return 0, ''

    operations = []

    if k > b_count:
        last_A = s.rfind('A')

        while b_count < k and last_A != -1:
            s = s[:last_A] + 'B' + s[last_A+1:]
            b_count += 1
            operations.append(last_A + 1)
            last_A = s.rfind('A')

        if b_count < k:
            operations.append(n)

    elif k < b_count:
        first_B = s.find('B')

        while b_count > k and first_B != -1:
            s = s[:first_B] + 'A' + s[first_B+1:]
            b_count -= 1
            operations.append(first_B + 1)
            first_B = s.find('B')

    return len(operations), '\n'.join(f'{op} B' for op in operations)

