def solve():
    inputs = []
    for line in sys.stdin:
        inputs.append(line.strip())

    index = 0
    def read():
        nonlocal index
        result = inputs[index]
        index += 1
        return result

    n, k = map(int, read().split(' '))
    s = read()

    posA = [i for i in range(n) if s[i] == 'A']
    posB = [i for i in range(n) if s[i] == 'B']

    def calculate_difference(pos):
        diff1 = abs(k - len(pos))
        k1, m1 = divmod(len(s), 2)
        if m1 and (pos[-1] + 1) // 2 > k1:
            return float('inf')
        elif pos[-1] < k1 * 2:
            diff2 = abs((k - k1 * 2) - len(pos))
        else:
            diff2 = float('inf')

        if diff1 == diff2 or (n % 2 and diff1 > diff2):
            return diff2
        else:
            return diff1

    diffA, diffB = calculate_difference(posA), calculate_difference(posB)
    min_diff = min(diffA, diffB)

    if min_diff == float('inf'):
        print(0)
        return

    operations = []
    def construct_operations(pos):
        nonlocal k
        for i in pos:
            operations.append(f'{i + 1} {s[i]}')
            s = list(s)
            s[i] = chr(ord(s[i]) ^ ord('A') ^ ord('B'))
            s = ''.join(s)
        k -= len(pos)

    if min_diff == diffA:
        construct_operations(posA)
    else:
        construct_operations(posB)

    operations.append(f'{posA[-1] + 2} A')
    k += 1

    while k > 0 and posB:
        for i in range(len(posB)):
            if (posB[i] + 1) // 2 <= len(s) // 2 and not s[posB[i]] == 'A':
                operations.append(f'{posB[i] + 1} B')
                k -= 1
                if k == 0: break

    print(len(operations))
    for operation in operations:
        print(operation)

