    wins_a = 0
    wins_b = 0
    current_wins_a = 0
    current_wins_b = 0

    for char in s:
        if char == 'A':
            current_wins_a += 1
            current_wins_b = 0
            if current_wins_a > current_wins_b:
                wins_a += 1
                current_wins_a = 0
                current_wins_b = 0
        else:
            current_wins_b += 1
            current_wins_a = 0
            if current_wins_b > current_wins_a:
                wins_b += 1
                current_wins_b = 0
                current_wins_a = 0

    for char in reversed(s):
        if char == 'A':
            current_wins_b = 0
            current_wins_a += 1
            if current_wins_a > current_wins_b:
                wins_a -= 1
                break
        else:
            current_wins_a = 0
            current_wins_b += 1
            if current_wins_b > current_wins_a:
                wins_b -= 1
                break

    return 'A' if wins_a >= wins_b else 'B'

