def solve():
    n = int(input())
    a = list(map(int, input().split()))

    two_powers = [2**i for i in range(int(math.log(n, 2))+1)]
    result = True
    for i, (x, y) in enumerate(zip(a[:-1],a[1:])):
        if(x > y):
            found = False
            for p in two_powers:
                if(i+1 <= p and not found):
                    found = True
                elif(i+1 > p and found):
                    break

            result &= found

    return "YES" if(result) else "NO"

