import collections
from functools import reduce

def solve():
    n = int(input())
    arr = [int(i) for i in input().split()]
    cnts = collections.Counter(arr)
    items = sorted(cnts.items(), key=lambda x: x[1], reverse=True)

    def check(items):
        return len(items) == 0 or sum(map(lambda x: abs(x[1] - items[0][1]), items)) <= max(0,items[0][1]-2)

    def merge(item):
        return (item[0], n-1-(item[1]))

    diff = list(filter(lambda x: x[1] != items[0][1], items))

    def solve_rec(items):
        if not check(items): return "NO"
        if len(diff) > 1 or (len(diff) == 1 and diff[0][1] != items[0][1]-1) : 
            merge_count = {key: items[1:][i][1] + items[i+2][1] for i, key in enumerate(items[1:-2]) if i % 2 == 0}
        else:
            merge_count = {key: merge(val) for key , val in diff}

        return solve_rec(list(merge_count.items()))

    return solve_rec(items) or "YES"

def solve(n):
    for x in range(1, n):
        if x % 3 == 0:
            continue
        for y in range(x+1, n-x):
            z = n - x - y
            if z <= y or z % 3 == 0:
                continue
            else:
                return "YES\n" + str(x) + " " + str(y) + " " + str(z)
    return "NO"

