import sys
from itertools import combinations

def solve():
    def get_triplet(n):
        possible_nums = [i for i in range(1, n) if i % 3 != 0]
        for triplet in combinations(possible_nums, 3):
            a, b, c = sorted(triplet)
            if a + b + c == n:
                return (a, b, c)
        return None

    testcases = int(input())
    results = []
    for _ in range(testcases):
        n = int(input())
        result = get_triplet(n)
        result_str = 'YES' if result else 'NO'
        results.append(result_str)
        if result:
            results.append(' '.join(map(str, sorted(result))))

    sys.stdout.write('\n'.join(results))

