def solve():
    # This will get overwritten for as many tests are there
    n = int(input())

    a = list(map(int, input().split()))

    def gen_next_b(prev_b):
        if prev_b == a[n - 1]:
            return prev_b + 1 
        else:
            return prev_b 

    initial_prev_b = 1

    b_values = [initial_prev_b] 
    current_b_value_holder = initial_prev_b 


    for x, y in zip(a[1:], a[:-1]):

        next_b_generator_lambda_func = lambda prev_b: max(current_b_value_holder + 1 , gen_next_b(prev_b))

        current_b_value_holder = next_b_generator_lambda_func(current_b_value_holder)

        if x == y:
            b_values.append( previous_b := current_b_value_holder ) 
        else:

            previous_b = current_b_value_holder

            if a[ a.index(x) +1 ] >  x and  (a[a.index(y)] == y): 
                next_b_to_handle_repeat_and_its_afterwards_element_value_plus_one_condition = max(previous_b, gen_next_b(a[a.index(x)])) 

                b_values.append( previous_b := next_b_to_handle_repeat_and_its_afterwards_element_value_plus_one_condition ) 

            else:   
                b_values.append(gen_next_b( current_b_value_holder )  if y == x +1 else max(current_b_value_holder , gen_next_b(previous_b)))       


    final_output = max(b_values[-1]   , a[n -1]) 

    return final_output


