import math

def solve():
    n, k = map(int, input().split())
    s = input()
    count = [0]
    for i in range(1, len(s)):
        if s[i] == 'W':
            count.append(count[-1])
        else:
            count.append(count[-1] + 1)

    min_val = math.ceil((count[-1]-1)/k + 1)
    result = min_val
    i = 0
    while i < len(s)-1:
        if s[i] != 'B':
            i += 1
            continue
        left_white_count = count[i]
        end = min(len(count), i+k+1)
        right_black_count = [x - left_white_count for x in count[:end]]
        next_smallest_b_index = i + k + 1
        while max(right_black_count) == 0:
            if next_smallest_b_index >= len(s):
                break
            i += 1
            end = min(len(count), i + k + 1)
            right_black_count = [x - left_white_count for x in count[:end]]
            min_val -= 1
        result = min(result, min_val)
        i += 1
    return result

