import numpy as np

def solve(x, y, n):
    diff = y - x - (n-2)  # Subtract minimum possible increase for n terms
    if diff < 0:
        return np.array([-1])

    arr = [x]
    step = diff // (n-2)
    remaining_diff = diff % (n-2)

    total_elements_added = 0

    for i in range(remaining_diff):
        arr.append(arr[-1] + step + 1)
    while len(arr) < n:
        arr.append(arr[-1] + step)

    return np.array(arr)


