from itertools import combinations

def solve(n, a):
    total_sum = sum(a)

    if len(a) == 1:
        return 'NO'

    for i in range(n, 0, -1):
        comb_list = list(combinations(range(len(a)), i))

        for subset in comb_list:
            A = [a[x] for x in subset]

            if sum(A) % 2 == (total_sum - sum(A)) % 2 and len(subset) > 0 and n-len(subset) > 0:
                return 'YES'

    return 'NO'

