def solve():
    # Attempt to read the number of responses and ensure it's within bounds (1-50)
    try:
        N = int(input())
        if not 1 <= N <= 50:
            raise ValueError("N is out of range")
    except ValueError as e:
        print(f"Invalid input for N: {e}")
        return

    max_quality, winner_index = -1, -1  # Initialize with sentinel values
    for idx in range(N):  
        try:
            a_i, quality = map(int, input().split())
            if not (a_i >= 0 and quality >= 0):
                raise ValueError("Inputs must be non-negative integers")
        except ValueError as e:
            print(f"Invalid input at response {idx+1}: {e}")
            continue

        # Check if this response is within the word limit and has higher quality than current max
        if a_i <= 10 and quality > max_quality:
            max_quality = quality
            winner_index = idx + 1  # Update winner index (1-based)

    # Ensure that at least one qualifying response was found
    if winner_index == -1:  
        print("No responses within the word limit.")
    else:  
        print(winner_index)  # Output winner index


