    for x in sorted([abs(a[i] - a[i-1]) for i in range(1, n)]):
        if len(heap) < k - 1:
            heapq.heappush(heap, -x)
        else:
            heapq.heappop(heap)
            heapq.heappush(heap, -x)

    return sum([-y for y in heap])

from heapq import heapify, heappop, heappush

def solve(n, k, a):
    h = [-abs(a[i] - a[i + 1]) for i in range(n - 1)]
    heapify(h)

    ans = 0
    for _ in range(k - 1):
        while h and h[0] == 0:
            heappop(h)
        if not h:
            break
        x = -heappop(h)
        ans += x

    return ans

def solve():
    b = [input(), input(), input()]

    def check_ways_to_win(board, symbol):
        win_conditions = [
            set([board[0][0], board[1][1], board[2][2]]),  # diagonal from top-left to bottom-right
            set([board[0][2], board[1][1], board[2][0]]),  # diagonal from top-right to bottom-left
        ]

        for i in range(3):  # rows and columns
            win_conditions.append(set([board[i][j] for j in range(3)]))  # row wins
            win_conditions.append(set([board[j][i] for j in range(3)]))  # column wins

        return any(len(condition) == 1 and symbol in condition for condition in win_conditions)

    symbol_wins = {
        "X": check_ways_to_win(b, "X"),
        "O": check_ways_to_win(b, "O"),
        "+": check_ways_to_win(b, "+")
    }

    winners = [symbol for symbol, win in symbol_wins.items() if win]
    return winners[0] if len(winners) == 1 else 'DRAW'

