def solve():
    n = int(input())
    level_count, node_at_level, total_nodes_on_levels_before, first_node_on_level = 0, None, 0, 0

    current_sum = 1

    while True:
        if level_count == 0:
            target_value = 2
        else:
            target_value = (math.comb(level_count + 1, 2) * 2)

        if total_nodes_on_levels_before < n and n <= target_value:
            current_sum += (first_node_on_level + n - first_node_on_level) / 2 * (n - first_node_on_level + 1)
            return int(current_sum)

        nodes_to_add = target_value - total_nodes_on_levels_before

        if level_count == 0:
            increment = 3
        else:
            increment = 2 * level_count + 3

        current_sum += (first_node_on_level + first_node_on_level + increment - 1) / 2 * nodes_to_add
        first_node_on_level += increment

        total_nodes_on_levels_before = target_value
        level_count += 1

