import math

def solve(x, k):
    if x % k != 0:
        return [x]

    i = k + (x - (k + 1))
    result = []

    # Add jumps until we are close enough to x to make a single jump
    while abs(i) > 1 and i != x: 
        if (abs(i) < x): 
            result.append(abs(i) * ((i > 0) * 2 - 1))
        else:
            result.append(x-i)
        i = (x - sum(result)) - (k + 1)

    if len(result):
        last_element_index = len(result)-1
        result[last_element_index] += x-sum(result[:last_element_index])

    return result

