def solve():
    s = input().strip()

    count = 0

    # Check for special case of single character string
    if len(s) == 1:
        return 2 - (s == '^')

    i = 0
    while i < len(s):
        # If current character is '_' and it's not part of a smiley face, increment count
        if s[i] == '_':
            if (i > 0 and s[i-1] != '^') or (i+1 < len(s) and s[i+1] != '^'):
                j = i + 1
                while j < len(s) and s[j] == '_':
                    j += 1
                count += max(0, j - i)
        # Move index forward to continue checking
        else:
            if i > 0 and s[i-1] == '^' and s[i] == '^' and (i+1 < len(s) or i-2 >= 0 and s[i-2] != '^'):
                count += 1
            elif i+1 < len(s) and s[i+1] == '^':
                count -= 1

        if i > -1:
          i = i + 1

    # If there is only one '^' character, we need to add at least 2 more characters
    if s.count('^') == 1:
        return max(2, count)

    return count

import re

def solve(s):
    s = '^' + s  # Adding '^' at the start for easier pattern matching.
    operations = 0

    # Using regex to find standalone characters or consecutive sequences not involving '^'.
    patterns = re.findall(r'(?<!\^)[_ ](?!\^)|(?<!\^)\^(?!\^)', s)

    if len(patterns) > 1:
        operations += (len(patterns)) - 1

    # Special handling when all characters are '_' or ' ': we need to add '^' at the end and count as operation.
    if set(s).issubset({' ', '_'}):
        operations += 1

    return max(0, operations)

