from collections import deque

def solve():
    # Input validation for number of iterations (for n)
    n = int(input())
    if not 2 <= n <= 10**9:
        raise ValueError("Input should be between 2 and 10^9")

    queue, visited = deque([(0, 0)]), set()

    while queue:
        curr_num, num_steps = queue.popleft()

        # Enforce maximum iteration depth constraint
        if num_steps > 40:
            break

        if curr_num == n:
            return True

        next_nums = [curr_num + i for i in range(1,4)]

        for next_num in next_nums:
            if next_num not in visited:
                visited.add(next_num)
                queue.append((next_num, num_steps+1))

    return False

