def solve():
    n, m = map(int, input().split())
    p = list(map(int, input().split()))

    d = OrderedDict()
    times = [-1] * (n + 1)

    for time, post_id in enumerate(p, start=1):
        if post_id in d:
            del d[post_id]

        elif len(d) == n: 
            oldest_post, _ = d.popitem(last=False)

            times[int(oldest_post)] = int(time)

        d[post_id] = None

    return ' '.join(map(str, times[1:]))

