        if is_corner(x, y): 
            return False
        return (x in [1, n] or y in [1, m])

    ans = 0

    if is_corner(x1, y1) and is_corner(x2, y2):
        ans = min(n, m)
    elif is_corner(x1, y1) or is_corner(x2, y2): 
        ans = 2
    else:
        ans = 4

    print(ans)

