import math

def neighbors(x, y):
    # Generate adjacent cell coordinates (x+dx, y+dy) within grid boundaries
    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nx, ny = x + dx, y + dy
        if 0 < nx <= n and 0 < ny <= m:  
            yield (nx, ny)

def count_neighbors(x, y):
    # Count the number of neighboring cells for a given cell
    return sum(1 for _ in neighbors(x, y))

def solve(n, m, x1, y1, x2, y2):
    if 0 < x1 <= n and 0 < y1 <= m and 0 < x2 <= n and 0 < y2 <= m:
        count_1 = count_neighbors(x1, y1)
        count_2 = count_neighbors(x2, y2)

        # Handle corner cases correctly
        if (x1 == 1 or x1 == n) and (y1 == 1 or y1 == m):  
            return min(6 + max(0, -4), 20)
        elif (x2 == 1 or x2 == n) and (y2 == 1 or y2 == m):  
            return min(count_1 + count_2, 20)
        else:
            # Handle odd-sized grids
            if n % 2 == 1 and m % 2 == 1:  
                return min(7 + max(0, -4), 20)

            # Standard case
            return min(count_1 + count_2, 20)  

    return "Invalid input"

def solve():
    n,m = map(int,input().split())
    if not (4 <= n <= 10**9 and 4 <= m <= 10**9):
        raise ValueError("Invalid input: n and m must be between 4 and 10^9")

