    def v(x, y):
        corners = [(1, 1), (1, m), (n, 1), (n, m)]
        if (x, y) in corners:
            return 2
        elif x in [1, n] or y in [1, m]:
            return 3
        else:
            return 4

    return min(v(x1,y1), v(x2,y2))

