    if (s1[0] == 'R' and s2[0] == 'B') or (s1[0] == 'B' and s2[0] == 'R'):
        return "YES"

    elif s1.count('B') != n1 // 2 + n1 % 2 or s2.count('B') != n2 // 2 + n2 % 2:
        return "NO"

    last_pop_1 = queue1.popleft()
    last_pop_2 = queue2.popleft()

    while queue1 or queue2:
