import math

def solve():
    # Number of dice 'n', sum of all dice values 's', sum of remaining dice after removing maximum 'r'
    n, s, r = map(int, input().split())

    if n == 1:  # Handle edge case where only one die is present
        return str(s)

    # Calculate initial repeated array to be closer or equal to the target sum when combined with other dice values
    ans = [math.ceil((s - (r + (n-2) * 1)) / (n - 1))] * (n - 1)

    # Adjust repeated values as needed to meet exactly 's'
    for i in range(1, n):
        if sum(ans) < s:
            ans[i] += 1

    return ' '.join(map(str, [r + (max(n-2,0)) * 1] + ans))

