import math

def solve():
    n, s, r = map(int, input().split())
    max_die_value = s - r

    # Ensure that max_die_value does not exceed 6
    if max_die_value > 6:
        return "Invalid input: max_die_value cannot be greater than 6"

    remaining_sum = r % (n - 1)
    quotient = int(math.ceil(r / (n - 1)))

    result = [max_die_value] + [quotient]*((r // (n - 1))*(n-2))

    # Distribute the remaining sum
    while remaining_sum > 0:
        for i in range(1, len(result)):
            if remaining_sum > 0 and result[i] < max_die_value:
                result[i] += min(max_die_value-result[i], remaining_sum)
                remaining_sum -= min(max_die_value-result[i], remaining_sum)

    return ' '.join([str(i) for i in result])

