def solve():
    n = int(input())
    s = input()

    def match(i, j):
        return s[i] == s[j]

    def check(start_idx):
        for i in range(0, (n // 2 - start_idx)):
            if not match(n-i-1-start_idx, i+start_idx) and not match(n-i-1, i):
                return False

        count_diff = sum(not match(i, n-i-1) for i in range((n // 2)+1))

        return count_diff <= 2*(start_idx) if start_idx != 0 else count_diff == 0

    for start_idx in range(min(3, (len(s) + 1) // 2)):
        if check(start_idx):
            print('Yes')
            sys.exit()
    print('No')

