import math

def count_odd(x):
    """Helper function to count odd numbers in an array"""
    return sum(1 for num in x if num % 2 != 0)

def find_triplet(arr, n):
    """Recursive helper function to find a triplet of indices with certain conditions"""
    def recursive_search(index, current_sum):
        if index == len(arr):
            return None
        new_sum = current_sum + arr[index]
        if new_sum % 2 != 0 and count_odd([arr[i] for i in range(len(arr)) if i not in [index, n]]]) > 1:
            return [index, n, -1]
        return recursive_search(index + 1, new_sum)
    return recursive_search(0, 0)

