def solve(n, a):
    total_sum = sum(a)
    best_sum = total_sum - 4

    for i in range(n-1):
        if a[i] == -1 and a[i+1] == -1:
            return total_sum + 4

        elif (a[i] == -1 and a[i+1] == 1) or (a[i] == 1 and a[i+1] == -1):
            current_sum = total_sum 
            best_sum = max(best_sum, current_sum)

    for i in range(n-1):
        if a[i] == 1 and a[i+1] == 1:
            return total_sum

    return best_sum 

