def solve():
    # Read input data
    n = int(input())
    arr = list(map(int, input().split()))

    # Initialize lists to hold intervals between messages for possible walks
    before_first_message_intervals = [(0, arr[0])]
    between_messages_intervals = []
    after_last_message_intervals = []  

    # Generate intervals between the messages as intended for walk times
    if n > 1:  
        for i in range(n - 1):
            start = max(0, arr[i] + 1)
            end = min(arr[i+1], arr[i] + 120)

            if end > start:
                between_messages_intervals.append((start, end))

    # Ensure intervals cover entire day including before first message and after last message for walks
    if len(before_first_message_intervals) > 0:
        before_first_message_intervals[-1] = (before_first_message_intervals[-1][0], arr[0])

    if len(after_last_message_intervals) > 0:
        after_last_message_intervals[0] = (arr[n-1], after_last_message_intervals[0][1])

    # Check each range of intervals that could fit a walk without overlap
    has_before_and_between_interval = any(x[0] <= y[0] and x[1] >= y[0] and len(before_first_message_intervals) > 0 for x, y in zip(between_messages_intervals, between_messages_intervals))
    possible_walks_without_overlap = all(isinstance(x, tuple) for x in before_first_message_intervals + between_messages_intervals + after_last_message_intervals)

    # Return output based on whether walk intervals are enough to accomodate two nonoverlapping walks
    if has_before_and_between_interval and (possible_walks_without_overlap or len(before_first_message_intervals)) and len(between_messages_intervals) > 0:
        return 'YES'
    else:
        return 'NO'

