def solve(s):
    def lexicographically_comparable(a, b):
        return a <= b

    for i in range(1, len(s)):
        for j in range(i + 1, len(s)):
            first = s[:i]
            second = s[i:j]
            third = s[j:]

            if ((lexicographically_comparable(first, second) and lexicographically_comparable(second, third)) 
                or (lexicographically_comparable(third, second) and lexicographically_comparable(second, first))):

                return "{} {} {}".format(first, second, third)

    return ''



