import re

def solve():
    s = input().strip()

    # Length and char validation for input str 's'
    if len(s) < 3:
        raise ValueError("Input string length should be more than or equal to 3")

    if not set(s).issubset('ab'):
        raise ValueError("Input string can contain characters only from the set {'a', 'b'}") 

    res1 = re.match(r'^(.).*\1(.*?)$', s)
    if res1:
        return ' '.join([res1.group(1), res1.group(2) + '.', '..'])

    res2 = re.match(r'^(..)(.*)$', s)
    if len(res2.group(2)) >= 3 and res2.group(1)[0] == res2.group(2)[0]:
        return ' '.join([res2.group(1), res2.group(2)[:3], res2.group(2)[3:]])

    n = min(len(s) // 3 + 1, len(s))
    a = s[:n]
    b = s[n:-n]
    c = '..' if n <= 1 else s[-n:]
    return ' '.join([a, b, c])

