def solve(a):
    def count_parity(x):
        parity = 0
        while x > 0:
            parity ^= (x & 1)
            x >>= 1
        return parity

    total_parity = functools.reduce(lambda acc, x: acc ^ count_parity(x), a, 0)

    if total_parity == 0:
        return 0

    min_operations = float('inf')

    for num in a:
        operations = 0
        while (num > 0):
            if count_parity(num) != count_parity(num // 2):
                break
            num //= 2
            operations += 1

        if.operations < min_operations:
            min_operations = operations

    return min_operations

