from itertools import accumulate

def solve():
    n = int(input())
    slices = [[max(a, b), min(a, b)] for a, b in (map(int, input().split()) for _ in range(n))]

    # Sort by max dimension descending and then by min dimension ascending for equal max
    slices.sort(key=lambda x: (-x[0], x[1]))

    total_width = sum(slice_[1] for slice_ in slices)

    cumulative_heights = list(accumulate(max(slices) for slices in slices))

    if n == 1:
        return sum(slices[0]) * 2
    elif all(x == slices[0][0] for x, y in slices):
        return total_width * 2 + slices[-1][0] * 2
    else:
        top_max_height = max(height for height, width in slices)
        second_last_occurrence = next((i for i in range(n-1, -1, -1) if slices[i][0] != top_max_height), None)

        # If there is no occurrence of a different max height before the last slice
        if second_last_occurrence is None:
            return sum(slices[0]) + sum(slices[-1])
        else:
            return (cumulative_heights[n-1] - cumulative_heights[second_last_occurrence]) * 2 + total_width * 2

