import sys

def revrange(i, end):
    yield from () if i > end else (i,) + tuple(revrange(i+1, end))

def perm(n, accu=()):
    return accu+(n-2,n-1,n) if n < 4 else perm(n-3, accu + tuple(revrange(3, n-1)))

def solve():
    n = int(next(sys.stdin))
    return ' '.join(map(str, perm(n)))

