from collections import defaultdict

def solve():
    n = int(input())
    words = [input().split() for _ in range(3)]

    counter = defaultdict(int)
    for i, word_list in enumerate(words):
        for word in word_list:
            counter[word] += 1 << i

    scores = [0, 0, 0]
    for count in counter.values():
        if count in [1, 4, 2]:  # Unique to the first or second player
            scores[0 if count & 1 else 1] += 3
        elif count == 3:       # Shared by both players
            scores[0] += 3
            scores[1] += 3

    return ' '.join(map(str, scores))

