def solve():
    n = int(input())
    res = [0] * 3
    words_a, words_b, words_c = input().split(), input().split(), input().split()

    counter_bc = c.Counter(words_c)
    res[0] += sum(map(lambda x: 3 if x not in counter_bc else (1 if counter_bc[x] == 1 and x not in c.Counter(words_a) or counter_bc[x] == 2 and x in c.Counter(words_b) else 0), words_a))

    counter_ac = c.Counter(words_c)
    for word in words_a:
        if word in counter_ac:
            counter_ac[word] += 1
    res[1] += sum(map(lambda x: 3 if x not in counter_ac else (1 if counter_ac[x] == 2 and x not in c.Counter(words_b) or counter_ac[x] == 3 and x in c.Counter(words_a) else 0), words_b))

    counter_ab = c.Counter(words_b)
    for word in words_a:
        if word in counter_ab:
            counter_ab[word] += 1
    res[2] += sum(map(lambda x: 3 if x not in counter_ab else (1 if len(counter_ab) == 0 and counter_ab[x] == 1 or counter_ab[x] == 2 and x not in c.Counter(words_c) else 0), words_c))

    return ' '.join(map(str, res))

