import sys

def solve(string):
    required_chars = ['T', 'i', 'm', 'r', 'u']

    # Validate all character types and their frequency counts match perfectly 
    if not all(char in string for char in required_chars):
        return "NO"
    if len(set(required_chars)) != len(set(string)):
        return "NO"

    # Additional check: Counting occurrence number on each letter across both strings 
    for i, j in zip(sorted(string), required_chars):  
          if i != j:
            return 'NO'

    return 'YES'

