def solve():
    n, k = map(int, input().split())
    result = []

    if k % 2 != 0:
        while n > 1:
            result.append((n - 1, n))
            n -= 2
    elif (k + 2) % 4 == 0 or k % 4 == 0 and n >= 4:
        i = 3 if k % 4 != 0 else 1
        while i <= n - 1:
            result.append((i, i + 1))
            i += 4
        n -= 2 * math.ceil((n - 1) / 4)
        if (k + n) % 4 == 0 and n > 0:
            result.append((2, n))

    print("YES" if len(result) > 0 else "NO")

    if len(result) > 0:
        for pair in result:
            print(pair[0], pair[1])

