import math

def solve():
    n = int(input().strip())

    def generate_numbers(start, end):
        if start == end:
            yield start
        else:
            mid = (start + end) // 2
            yield from generate_numbers(start, mid)
            yield from generate_numbers(mid+1, end)

    res = sum(math.floor(n / x) ** 2 if x in [1] else math.floor(n // x) * (math.floor(n // x) - 1) + math.floor(n / 3) for x in generate_numbers(1, int(math.sqrt(n))))

    return res

