import functools

@functools.lru_cache(maxsize=None)
def solve(n):
    digits = '123456789'
    result = [0] * 10

    def backtrack(index, sum):
        if sum == n:
            nonlocal result
            temp = []
            for i in range(1, 10):
                temp.extend([i]*result[i])
            result = temp[:]
            return True  

        for i in range(len(digits) - index):
            digit = int(digits[index + i])

            if sum + digit <= n:
                nonlocal result
                result[digit] += 1

                if backtrack(index+i+1,sum+digit): 
                    return True

                result[digit] -= 1

        return False 

    backtrack(0,0)

    return ''.join(map(str,result))

