import bisect

def solve():
    n = int(input())
    A = list(map(int, input().split()))

    def unique_from_end(array):
        if not array:
            return []

        unique_elements = unique_from_end(array[1:])

        if array[0] not in unique_elements:
            unique_elements.insert(0, array[0])

        return unique_elements

    # Apply bisect_left only to the sorted version of A.
    r_a_s = sorted(A)

    def binary_search(arr, target):
        low = 0
        high = len(arr) - 1

        if not arr:
            return None
        if high <= 0:
            return int(arr[0] == target)

        middle = (low + high) // 2

        if arr[middle] == target:
            return middle
        elif arr[middle] > target:
            return binary_search(arr[:middle], target)
        else:
            result_of_right_side = binary_search(arr[middle+1:], target)
            return None if result_of_right_side is None else 1 + (len(arr[:middle]) if arr[middle] < target else middle) + result_of_right_side

    def find_indexes(unique_elements, r_a_s):
        if not unique_elements:
            return []

        current_index = binary_search(r_a_s, unique_elements[0])

        return [current_index] + (find_indexes(unique_elements[1:], r_a_s) if len(unique_elements) > 1 else [])

    indexes = find_indexes(unique_from_end(reversed(A)), r_a_s)
    max_index = max(indexes)

    def calculate_psums(psums, i):
        psums[i] += 1
        new_index = binary_search(psums[:i], None) if any(psums[:i]) else 0
        if len(psums[new_index:]) < max_index - new_index:
                additional_values_count = max_index + 1 - (new_index + len(psums[new_index:]))
                psums.extend([0] * additional_values_count)

        for new_i in range(len(psums) - 2, new_index-2 if new_index else -3,-1):
            if psums[new_i+1]:
                break
            psums[new_i + 1] += psums[new_i]

    indexes.reverse()

    psums = [0] * (max_index + 1)

    for i in indexes:
        calculate_psums(psums, i)

    return min(psums)

def solve():
    # Input: 
    point_count = int(input())

    if point_count == 0:
        print(0)
        return

    points = []

    for _ in range(point_count):
        x, y = map(int, input().split())
        points.append((x, y))

    # Calculate total distances along X and Y axes
    min_x = max_x = points[0][0]
    min_y = max_y = points[0][1]

    for point in points:
        if point[0] < min_x:
            min_x = point[0]
        elif point[0] > max_x:
            max_x = point[0]

        if point[1] < min_y:
            min_y = point[1]
        elif point[1] > max_y:
            max_y = point[1]

    # Output: 
    total_distance = (max_x - min_x) + (max_y - min_y)
    print(total_distance)

