def solve():
    n = int(input())

    if n == 1:
        return '1'

    perm_list = [0] * (n+2)
    pos = [True] * (n + 2)
    first = []

    for i in range(3, n + 1):
        num = n - i
        x = 2
        idx = 1

        while math.gcd(x, num) != 1 or math.gcd(idx, n) != 1:
            if pos[x]:
                perm_list[idx] = x 
                first.append(idx)
                pos[x] = False  
            idx += 1;  
            x += 1  

        perm_list[n - (i // 2)] = num 
        perm_list[(n - i // 2) + 1] = n
        pos[n] = False 

    if len(first):
        perm_list[2] = first[-1]
        perm_list[first[-1]] = 2

    if n % 2 == 0:
        perm_list[1] = n-1
        perm_list[n - 1] = 1   

    return ' '.join(str(val) for val in perm_list[1:])

