import math

def solve(n):
    """
    Generate permutations of length n that minimize weight.

    Args:
        n (int): The length of the permutation.

    Returns:
        A string representing a permutation with minimized weight.
    """

    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input should be a positive integer.")

    result = []

    for i in range(1, n + 1):
        # Swap certain elements to minimize weight
        if i % 2 == 0:
            result.append(i // 2)
        else:
            result.append(n - (i - 1) // 2)

    return ' '.join(map(str, result))

