    n, m = map(int, input().split())
    a, b = input(), input()

    while len(a) > 0 and len(b) > 0:
        if a[-1] == b[-1]:
            a = a[:-1]
            b = b[:-1]
        else:
            break

    if len(b) == 0:
        return "YES"
    elif b[0] in a:
        for i in range(len(a)):
            if a[i] == b[0]:
                for j in range(i+1, len(a)):
                    if (b[0]=='0' and a[j] != '0') or (b[0]=='1' and a[j] != '1'):
                        break;
                    if(j==len(a)-1):
                        return "YES"
    return "NO"

