import sys

def solve():
    n, m = map(int, input().split())
    b = input().strip()
    a = input().strip()

    idx_a = len(a) - len(b) + 1;
    if a[idx_a:] != b[1:]:
        return "NO"
    def compare(idx):
        return 'YES' if idx <= len(a)-m+ 1 and a[idx] == b[0] else ('NO' if idx > len(a) else compare(idx + 1))
    return compare(1)

