from collections import defaultdict

def solve():
    problems_solved = defaultdict(int)
    total_balloons = 0

    n = int(input())
    s = input()

    for problem in s:
        if problems_solved[problem] == 0:
            total_balloons += 2
        else:
            total_balloons += 1

        problems_solved[problem] += 1

    return total_balloons

def solve():
    n = int(input())
    s = input()
    result = 0
    first_solved = {}
    for char in s:
        result += 1 + (char not in first_solved)
        first_solved[char] = True
    return str(result)

import collections

def solve(n, s):
    freq = collections.defaultdict(int)
    return len(s) + sum(1 for char in s if not (freq[char] := freq[char] + 1) - 1)

def solve():
    n = int(input())
    s = input()
    counter = {}
    for char in s:
        if char in counter:
            counter[char] += 1
        else:
            counter[char] = 1
    total_balloons = sum(v + (v > 0) for v in counter.values())
    print(total_balloons)

