import math

def solve(s):
    unique_letters = [0] * 26
    total_days = 0
    day_letter_count = 0

    for char in s:
        index = ord(char) - ord('a')

        if not unique_letters[index]:
            unique_letters[index] += 1
            day_letter_count += 1

            total_days += max(0, math.ceil(day_letter_count / 3) - math.floor((day_letter_count-1)/3))

    return max(total_days, 1)

