import sys

def solve():
    n = int(input())

    res = []
    if n == 2:
        return 2, ' '.join(map(str, [2, 1]))
    elif n % 2 != 0:
        m = n - 3
        d = 2
        for i in range(1, (n + 1) // 2):
            res.append(m + i * 2)
            if i == 1:
                res.append(1)
    else:
        m = n - 2
        d = 2
        res[0:0] = map(str, range((m + 2), (n + 1) + 1, 2))
        for _ in range(m // 4):
            temp = []
            for i in [3, 5]:
                temp.extend([i*2-1, i*2])
            res[0:0] = map(str, temp)

    return d, ' '.join(res)

import itertools

def solve():
    n = int(input())
    d = 2
    perm = list(range(1, n+1))
    result = []

    # Split permutation into pairs
    for i in range(0, len(perm), 2):
        if i + 1 < len(perm):
            pair = [perm[i], perm[i+1]]
        else:
            pair = [perm[i]]

        # Reverse the order of the pair (except for the last element)
        if i > 0:
            result.extend(reversed(pair))
        else:
            result.extend(pair)

    return f"{d}\n" + " ".join(map(str, result))

import sys

def solve():
    # Initialize a list to store occurrences of "1" values in the input grid
    grass = []
    for _ in range(4):
        x = int(input().strip())
        if x == 1:
            grass.append(x)

    # Return moves based on the number of "1" values in the grid
    return 0 if len(grass) == 0 else (1 if len(grass) < 4 else 2)

