import sys

def solve():
    n, m = [int(x) for x in input().split()]

    dp = [[2 * i + 2 * j + 1 for j in range(m)] for i in range(n)]

    for i in range(1, n):
        for j in range(1, m):
            cost = (m * i) + j + 1
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + cost

    return str(dp[n-1][m-1])

def solve(n, m):
    return ((n) *m*(m+n))//2 +( n*m)


#or alternatively

def solve():
    n, m = map(int, input().split())
    return (m-1)*(2*n+m-1) + (n-m)*m if n > m else (n-1)*(2*m+n-1) + (m-n)*n
